package com.sstar.video;

import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.OpenableColumns;import android.view.*;import android.widget.*;import android.graphics.Color;import android.graphics.Typeface;
import org.json.*;import java.util.concurrent.*;import java.io.*;

public class MainActivity extends Activity {
  final ExecutorService io=Executors.newSingleThreadExecutor(); Supabase api; LinearLayout root,content,bar; EditText email,password; TextView status; JSONArray videos=new JSONArray();
  static final int PICK_VIDEO=41; int dark=Color.rgb(22,24,29), accent=Color.rgb(110,76,255);
  public void onCreate(Bundle b){super.onCreate(b);api=new Supabase(this);getWindow().setStatusBarColor(dark);getWindow().setNavigationBarColor(dark);showHome();}
  TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(16,12,16,12);return t;}
  Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
  void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(247,247,250));setContentView(root);TextView h=text(title,23,Color.WHITE);h.setTypeface(null,Typeface.BOLD);h.setBackgroundColor(dark);root.addView(h);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setPadding(14,10,14,24);content.setOrientation(1);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
  boolean requireAuth(){if(!api.accessToken.isEmpty())return true;new AlertDialog.Builder(this).setTitle("Sign in required").setMessage("Create an account or sign in to upload videos, go live, comment and follow creators. You can browse public videos without an account.").setNegativeButton("Later",null).setPositiveButton("Sign in",(d,w)->showAuth()).show();return false;}
  void showAuth(){base("S ☆");content.addView(text("Connect with your community",18,dark));email=new EditText(this);email.setHint("Email");email.setInputType(33);content.addView(email);password=new EditText(this);password.setHint("Password");password.setInputType(129);content.addView(password);Button login=button("Sign in");content.addView(login);Button signup=button("Create account");content.addView(signup);status=text("",14,Color.RED);content.addView(status);login.setOnClickListener(v->auth(false));signup.setOnClickListener(v->auth(true));}
  void auth(boolean create){String e=email.getText().toString().trim(),p=password.getText().toString();if(e.isEmpty()||p.length()<6){status.setText("Enter a valid email and password (6+ characters).");return;}status.setText("Connecting…");io.execute(()->{try{JSONObject body=new JSONObject();body.put("email",e);body.put("password",p);JSONObject r=api.request("POST",create?"/auth/v1/signup":"/auth/v1/token?grant_type=password",body,null);JSONObject u=r.optJSONObject("user");if(u==null)u=r.optJSONObject("data");String tok=r.optString("access_token","");String uid=u==null?"":u.optString("id","");if(tok.isEmpty()||uid.isEmpty())throw new Exception(create?"Check your email to confirm the account, then sign in.":"No active session returned.");api.save(tok,uid,e);runOnUiThread(this::showHome);}catch(Exception ex){runOnUiThread(()->status.setText(ex.getMessage()));}});}
  void showHome(){base("S ☆   ·   Discover");bar=new LinearLayout(this);bar.setOrientation(0);Button feed=button("Feed"),upload=button("Upload"),live=button("Live"),profile=button("Profile"),account=button(api.accessToken.isEmpty()?"Sign in":"Sign out");bar.addView(feed,new LinearLayout.LayoutParams(0,-2,1));bar.addView(upload,new LinearLayout.LayoutParams(0,-2,1));bar.addView(live,new LinearLayout.LayoutParams(0,-2,1));bar.addView(profile,new LinearLayout.LayoutParams(0,-2,1));bar.addView(account,new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);status=text("Public videos · Browse without signing in",14,dark);root.addView(status);feed.setOnClickListener(v->loadFeed());upload.setOnClickListener(v->{if(requireAuth())pickVideo();});live.setOnClickListener(v->{if(requireAuth())startActivity(new Intent(this,LiveHubActivity.class));});profile.setOnClickListener(v->{if(requireAuth())showProfile();});account.setOnClickListener(v->{if(api.accessToken.isEmpty())showAuth();else{api.logout();showHome();}});loadFeed();}
  void loadFeed(){status.setText("Loading feed…");io.execute(()->{try{JSONObject r=api.request("GET","/rest/v1/videos?select=id,owner_id,title,description,video_url,created_at&visibility=eq.public&order=created_at.desc&limit=50",null,null);videos=r.optJSONArray("data");if(videos==null)videos=new JSONArray();runOnUiThread(()->renderFeed());}catch(Exception e){runOnUiThread(()->status.setText("Feed error: "+e.getMessage()));}});}
  void renderFeed(){content.removeAllViews();content.addView(text("Videos · Latest",19,dark));if(videos.length()==0){content.addView(text("No public videos yet. Upload the first one.",15,dark));return;}for(int i=0;i<videos.length();i++){JSONObject item=videos.optJSONObject(i);if(item==null)continue;LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setBackgroundColor(Color.WHITE);card.setPadding(8,8,8,14);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=18;content.addView(card,cp);String title=item.optString("title","Video");card.addView(text(title,18,dark));String owner=item.optString("owner_id","");if(!owner.isEmpty()&&!owner.equals(api.userId)){Button follow=button("Follow creator");card.addView(follow);follow.setOnClickListener(v->toggleFollow(owner,follow));}String videoId=item.optString("id","");Button like=button("♥ Like");card.addView(like);like.setOnClickListener(v->toggleLike(videoId,like));card.addView(text(item.optString("description",""),14,Color.DKGRAY));String url=item.optString("video_url","");if(!url.isEmpty()){VideoView player=new VideoView(this);player.setVideoURI(Uri.parse(url));card.addView(player,new LinearLayout.LayoutParams(-1,560));Button play=button("Play video");card.addView(play);play.setOnClickListener(v->player.start());}Button comments=button("Comments");card.addView(comments);comments.setOnClickListener(v->showComments(item.optString("id")));}}
  void pickVideo(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("video/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_VIDEO);}
  protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==PICK_VIDEO&&res==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);uploadVideo(uri);}}
  String displayName(Uri uri){try(Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int n=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(n>=0)return c.getString(n);}}return "video.mp4";}
  void uploadVideo(Uri uri){final EditText title=new EditText(this);title.setHint("Video title");new AlertDialog.Builder(this).setTitle("Name your video").setView(title).setNegativeButton("Cancel",null).setPositiveButton("Upload",(d,w)->{String name=title.getText().toString().trim();if(name.isEmpty())name=displayName(uri);final String t=name;status.setText("Uploading…");io.execute(()->{try{String path=api.userId+"/"+System.currentTimeMillis()+"_"+displayName(uri).replaceAll("[^A-Za-z0-9._-]","_");String publicUrl=api.upload(path,uri);JSONObject row=new JSONObject();row.put("owner_id",api.userId);row.put("title",t);row.put("description","");row.put("video_url",publicUrl);row.put("visibility","public");api.request("POST","/rest/v1/videos",row,"return=minimal");runOnUiThread(()->{status.setText("Upload complete");loadFeed();});}catch(Exception e){runOnUiThread(()->status.setText("Upload failed: "+e.getMessage()));}});}).show();}
  void showComments(String videoId){if(!requireAuth())return;EditText input=new EditText(this);input.setHint("Write a comment");new AlertDialog.Builder(this).setTitle("Add comment").setView(input).setNegativeButton("Close",null).setPositiveButton("Send",(d,w)->{String body=input.getText().toString().trim();if(body.isEmpty())return;io.execute(()->{try{JSONObject row=new JSONObject();row.put("video_id",videoId);row.put("user_id",api.userId);row.put("body",body);api.request("POST","/rest/v1/comments",row,"return=minimal");runOnUiThread(()->Toast.makeText(this,"Comment sent",Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show());}});}).show();}
  void showProfile(){base("Profile");content.addView(text("Signed in as\n"+api.email,18,dark));EditText display=new EditText(this);display.setHint("Display name");content.addView(display);EditText username=new EditText(this);username.setHint("Username");content.addView(username);EditText bio=new EditText(this);bio.setHint("Bio");content.addView(bio);Button save=button("Save profile");content.addView(save);save.setOnClickListener(v->{try{JSONObject row=new JSONObject();row.put("id",api.userId);row.put("display_name",display.getText().toString().trim());row.put("username",username.getText().toString().trim());row.put("bio",bio.getText().toString().trim());io.execute(()->{try{api.request("POST","/rest/v1/profiles",row,"resolution=merge-duplicates,return=minimal");runOnUiThread(()->Toast.makeText(this,"Profile saved",Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show());}});}catch(Exception e){}});Button out=button("Sign out");content.addView(out);out.setOnClickListener(v->{api.logout();showAuth();});}
  void toggleFollow(String creatorId,Button b){if(!requireAuth())return;io.execute(()->{try{String q="/rest/v1/follows?follower_id=eq."+api.userId+"&followed_id=eq."+creatorId;JSONObject found=api.request("GET",q,null,null);JSONArray a=found.optJSONArray("data");if(a!=null&&a.length()>0){api.request("DELETE",q,null,null);runOnUiThread(()->b.setText("Follow creator"));}else{JSONObject row=new JSONObject();row.put("follower_id",api.userId);row.put("followed_id",creatorId);api.request("POST","/rest/v1/follows",row,"return=minimal");runOnUiThread(()->b.setText("Following"));}}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Follow failed: "+e.getMessage(),Toast.LENGTH_LONG).show());}});}
  void toggleLike(String videoId,Button b){if(!requireAuth())return;io.execute(()->{try{String q="/rest/v1/video_likes?user_id=eq."+api.userId+"&video_id=eq."+videoId;JSONObject found=api.request("GET",q,null,null);JSONArray a=found.optJSONArray("data");if(a!=null&&a.length()>0){api.request("DELETE",q,null,null);runOnUiThread(()->b.setText("♥ Like"));}else{JSONObject row=new JSONObject();row.put("user_id",api.userId);row.put("video_id",videoId);api.request("POST","/rest/v1/video_likes",row,"return=minimal");runOnUiThread(()->b.setText("♥ Liked"));}}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Like failed: "+e.getMessage(),Toast.LENGTH_LONG).show());}});}
  protected void onDestroy(){super.onDestroy();io.shutdown();}
}
